-- A claim's due-by, fixed when it is made: its date plus the terms of its person's grade on that date
-- (the sheet's terms when the grade has none of its own). Claims made before terms were kept per grade
-- are due by their date plus the sheet's terms (14 when never set).
ALTER TABLE claim ADD COLUMN due_by DATE;
UPDATE claim c SET due_by = DATEADD(DAY, COALESCE((SELECT CAST(s.setting_value AS INT) FROM setting s
    WHERE s.sheet_id = c.sheet_id AND s.setting_key = 'terms' AND s.setting_value <> ''), 14), c.claim_date);
ALTER TABLE claim ALTER COLUMN due_by SET NOT NULL;
-- A claim's status log, oldest first (by id): each status it has had, who gave it, the sheet's today then,
-- and its due as shown at that moment ("n/a" when it had none). Claims made before the log have none.
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
    status    VARCHAR(16)  NOT NULL,
    by_user   VARCHAR(255) NOT NULL,
    logged_on DATE         NOT NULL,
    due       VARCHAR(32)  NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, claim_id, id);
-- A person's holds, each from its from-date to its to-date inclusive (no to-date: open-ended). A person may
-- have several over time. Only their OPEN (and PENDING) claims dated within a hold and not bound by a statement
-- are left out of the live totals. A person held before holds were dated is held from the beginning of time.
CREATE TABLE person_hold (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE   NOT NULL,
    to_date   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id, from_date);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- A rate may carry a to-date: it applies through that date (null: with no end). Never before its from-date.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- Closing a period fixes each person's due-total for it too: one row per person on the sheet at that
-- moment. Reopening drops them; a person added while it is closed has no row (their figure is 0.00).
CREATE TABLE period_person_total (
    sheet_id    VARCHAR(255)   NOT NULL,
    period_name VARCHAR(255)   NOT NULL,
    person_id   BIGINT         NOT NULL,
    total       DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
-- A setting that carries a figure (the clerk limit, the floor, the terms and each grade's terms, the late percent,
-- the cap) is dated: one value per from-date, in force from that date until the next one. A blank value is none
-- (no clerk limit, no cap). The policy date and the period numbering from-date stay undated, in setting.
CREATE TABLE setting_from (
    sheet_id      VARCHAR(255) NOT NULL,
    setting_key   VARCHAR(64)  NOT NULL,
    from_date     DATE         NOT NULL,
    setting_value VARCHAR(255) NOT NULL,
    PRIMARY KEY (sheet_id, setting_key, from_date)
);
-- A value saved before settings were dated was in force on every date.
INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value)
    SELECT sheet_id, setting_key, DATE '0001-01-01', setting_value FROM setting
    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');
DELETE FROM setting
    WHERE setting_key IN ('clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap');

