};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts and voided
 * ones do not, nor do a person's open claims dated within one of their holds, unless a statement bound them.
 */
export const counts = (c: Claim, people: Person[]) =>
  c.status === 'SETTLED' ||
  (isOpen(c) &&
    ((c.stated && c.status !== 'PENDING') || !heldOn(people.find((p) => p.id === c.personId), c.date)));

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export const claimsQuery = (sheetId: string) => ({
  queryKey: claimsKey(sheetId),
  queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
});

/** Amounts are added up in whole cents, so the sum shows exactly with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { patronIdsOf, patronsQuery } from '../patrons/patronsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { excess, figure, personDue, personSum, ratesQuery, sumDue } from './ratesQuery';

function useSheetData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
    cap: useCap(sheetId),
  };
}

function ClaimDue({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { people, rates, floor, late } = useSheetData(sheetId);
  const person = people.find((p) => p.id === claim.personId);
  return <td data-testid="claim-due">{figure(claim, rates, person, floor, late)}</td>;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  return <td data-testid="person-due-total">{personDue(people.find((p) => p.id === personId), people, claims, rates, today, floor, late, cap)}</td>;
}

/** What a person's figures add up to above the sheet's cap; 0.00 when they are not above it. */
function PersonExcess({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  return <td data-testid="person-excess">{excess(personSum(people.find((p) => p.id === personId), people, claims, rates, today, floor, late), cap)}</td>;
}

/** A person's backing: their patrons' due-totals added up, skipping n/a; 0.00 with no patrons. */
function PersonBacking({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  const ids = patronIdsOf(useQuery(patronsQuery(sheetId)).data ?? [], personId);
  const dues = people.filter((p) => ids.includes(p.id)).map((p) => personDue(p, people, claims, rates, today, floor, late, cap));
  return <td data-testid="person-backing">{sumDue(dues)}</td>;
}

/** The sheet's due-total: every person's due-total added up, skipping n/a. */
export function useSheetDueTotal(sheetId: string) {
  const { people, claims, rates, today, floor, late, cap } = useSheetData(sheetId);
  return sumDue(people.map((p) => personDue(p, people, claims, rates, today, floor, late, cap)));
}

function DueTotal({ sheetId }: { sheetId: string }) {
  return (
    <p data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{useSheetDueTotal(sheetId)}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  PersonHeaders.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 15, Component: PersonDueTotal }),
  PersonHeaders.fill({ order: 16, Component: () => <th>Excess</th> }),
  PersonCells.fill({ order: 16, Component: PersonExcess }),
  PersonHeaders.fill({ order: 22, Component: () => <th>Backing</th> }),
  PersonCells.fill({ order: 22, Component: PersonBacking }),
  SheetPanel.fill({ order: 25, Component: DueTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import type { Person } from '../people/peopleQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useFloor, useLate } from '../settings/settingsQuery';
import { figure, isOverdue, ratesQuery, sumDue } from './ratesQuery';

function useOverdueData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
  };
}

type OverdueData = ReturnType<typeof useOverdueData>;

/** The overdue claims that count (a held person's OPEN claims do not), of one person or of the sheet, with their figures, late charges included. */
function overdue({ people, claims, rates, today, floor, late }: OverdueData, person?: Person) {
  const overdueClaims = claims.filter(
    (c) => (!person || c.personId === person.id) && counts(c, people) && isOverdue(c, today),
  );
  const figures = overdueClaims.map((c) => figure(c, rates, people.find((p) => p.id === c.personId), floor, late));
  return { count: overdueClaims.length, total: sumDue(figures) };
}

function ClaimDueBy({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const today = useSheetToday(sheetId);
  return (
    <>
      <td data-testid="claim-due-by">{claim.dueBy}</td>
      <td data-testid="claim-overdue">{isOverdue(claim, today) ? 'yes' : 'no'}</td>
    </>
  );
}

function PersonOverdue({ sheetId, personId }: { sheetId: string; personId: number }) {
  const data = useOverdueData(sheetId);
  const person = data.people.find((p) => p.id === personId);
  const { count, total } = person ? overdue(data, person) : { count: 0, total: '0.00' };
  return (
    <td>
      <span data-testid="person-overdue-count">{count}</span> /{' '}
      <span data-testid="person-overdue-total">{total}</span>
    </td>
  );
}

/** The sheet's overdue claims that count: how many, and their total. */
export function useSheetOverdue(sheetId: string) {
  return overdue(useOverdueData(sheetId));
}

function OverdueTotal({ sheetId }: { sheetId: string }) {
  const { count, total } = useSheetOverdue(sheetId);
  return (
    <p data-testid="rollup-overdue">
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong> totalling{' '}
      <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 12, Component: ClaimDueBy }),
  PersonHeaders.fill({ order: 16, Component: () => <th>Overdue</th> }),
  PersonCells.fill({ order: 16, Component: PersonOverdue }),
  SheetPanel.fill({ order: 26, Component: OverdueTotal }),
];
import { ClaimCells } from '../../slots/defs/claimColumns';
import type { Claim } from './claimsQuery';

/** Who opened the claim (blank until it is opened). */
function ClaimOpenedBy({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-opened-by">{claim.openedBy ?? ''}</td>;
}

export const contribution = ClaimCells.fill({ order: 25, Component: ClaimOpenedBy });
import { defineSlot } from '../Slot';
import type { Claim } from '../../features/claims/claimsQuery';

/**
 * A person's claims table, column by column. A feature that shows something per claim contributes
 * a <td>, rendered in each claim's row after its own cells.
 */
export const ClaimCells = defineSlot<{ sheetId: string; claim: Claim }>('claim.cells');

