export function roundsHalfUp(claim: Claim, { policy, claims }: Late): boolean {
  const corrected = isCorrection(claim) && claim.corrects !== null
    ? claims.find((c) => c.personId === claim.personId && c.number === claim.corrects)
    : undefined;
  return (corrected ?? claim).date < policy;
}

/** An open (OPEN or PENDING) claim whose due-by (fixed when it was made) is before the sheet's today. */
export const isOverdue = (claim: Claim, today: string) => isOpen(claim) && today !== '' && claim.dueBy < today;

/** The full 30 days the claim has been overdue on the sheet's today (0 when it is not overdue). */
function lateMonths(claim: Claim, { today }: Late): bigint {
  if (!isOverdue(claim, today)) return 0n;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.dueBy}T00:00:00Z`)) / 86_400_000;
  return BigInt(Math.floor(days / 30));
}

/**
 * A claim's figure: a settled claim's frozen due (its late charge frozen in), otherwise the figure its
 * person's last statement bound it to (a PENDING claim is not bound: it shows its live figure), otherwise its amount times the rate, on the claim's date, of
 * the grade its person had on that date (rounded by the policy date, see `roundsHalfUp`), raised to the sheet's `floor` in force on the claim's date (two decimals). An overdue claim's late charge — the late
 * percent in force on the claim's date of that figure for every full 30 days overdue — is added on top: a statement
 * never binds it, so it follows the sheet's today. A correction has neither floor nor late charge.
 */
export function figure(claim: Claim, rates: Rate[], person: Person | undefined, floor: DatedValue[], late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const halfUp = roundsHalfUp(claim, late);
  const live = due(claim.amount, rateFor(rates, gradeOn(person, claim.date), claim.date), halfUp);
  const bound = claim.stated && claim.status !== 'PENDING' ? (claim.statedDue ?? 'n/a') : isCorrection(claim) ? live : floored(live, valueOn(floor, claim.date) ?? DEFAULT_FLOOR);
  const months = isCorrection(claim) ? 0n : lateMonths(claim, late);
  if (bound === 'n/a' || months === 0n) return bound;
  return show(hundredths(bound) + dueCents(show(hundredths(bound) * months), valueOn(late.pct, claim.date) ?? DEFAULT_LATE_PCT, halfUp));
}

function floored(live: string, floor: string): string {
  return live === 'n/a' || hundredths(live) >= hundredths(floor) ? live : show(hundredths(floor));
}

/**
 * A person's figures added up, before the cap: the sum of their counting claims' rounded figures, as each claim shows it. With no rate today and no figure it is n/a; otherwise it is the sum of the figures there are.
 */
export function personSum(person: Person | undefined, people: Person[], claims: Claim[], rates: Rate[], today: string, floor: DatedValue[], late: Late): string {
  if (!person) return 'n/a';
  const rate = rateFor(rates, gradeOn(person, today), today);
  const figures = claims
    .filter((c) => c.personId === person.id && counts(c, people))
    .map((c) => figure(c, rates, person, floor, late))
    .filter((d) => d !== 'n/a');
  return rate === undefined && figures.length === 0 ? 'n/a' : sumDue(figures);
}

/** A sum of figures held to the sheet's `cap` (two decimals; "" for none); n/a is not capped. */
export function capped(sum: string, cap: string): string {
  return sum === 'n/a' || cap === '' || hundredths(sum) <= hundredths(cap) ? sum : show(hundredths(cap));
}

/** What a sum of figures is above the sheet's `cap`: 0.00 when it is not (or there is no cap, or it is n/a). */
export function excess(sum: string, cap: string): string {
  return sum === 'n/a' ? '0.00' : show(hundredths(sum) - hundredths(capped(sum, cap)));
}

import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { claimsQuery, counts, sumAmounts } from './claimsQuery';

function useCounting(sheetId: string) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  return (useQuery(claimsQuery(sheetId)).data ?? []).filter((c) => counts(c, people));
}

function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useCounting(sheetId);
  return <td data-testid="person-claimed">{sumAmounts(claims.filter((c) => c.personId === personId))}</td>;
}

function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useCounting(sheetId);
  return (
    <p data-testid="rollup">
      Claimed total <strong data-testid="rollup-claimed-total">{sumAmounts(claims)}</strong>
    </p>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 10, Component: () => <th>Claimed</th> }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
  SheetPanel.fill({ order: 20, Component: ClaimedTotal }),
];
 * closed it is the figure fixed when it was closed (0.00 for a person added since).
 */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedValue[],
  late: Late,
): string {
  if (period.closed) return period.personTotals[String(person.id)] ?? '0.00';
  return sumDue(
    claims
      .filter((c) => c.personId === person.id && counts(c, people) && period.from <= c.date && c.date <= period.to)
      .map((c) => figure(c, rates, person, floor, late)),
  );
}

/** A period's due-total: its people's due-totals for it added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], floor: DatedValue[], late: Late): string {
  return sumDue(people.map((p) => personPeriodDue(period, p, claims, people, rates, floor, late)));
}

