package net.officefloor.hq.app.claim;

/**
 * Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID. A clerk's
 * settle of a claim whose due is above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED)
 * or rejects it (back to OPEN).
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code next}. */
    public boolean allows(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT || this == PENDING;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status is open: OPEN, or PENDING, which is handled like OPEN in every total. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status counts toward the totals: an open or a SETTLED one. */
    public boolean counts() {
        return isOpen() || this == SETTLED;
    }

    /** The audit event of a change from {@code from} to this status. */
    public String event(ClaimStatus from) {
        if (from == PENDING) {
            return this == SETTLED ? "CLAIM_APPROVED" : this == OPEN ? "CLAIM_REJECTED" : event();
        }
        return event();
    }

    /** The audit event of a change to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimResettled {
    public void audit(@Val Claim loaded, @Val Resettled resettled, People people, ServerHttpConnection connection,
            Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        List<String> fields = new ArrayList<>(List.of("person=" + (person == null ? "" : person.name()),
                "amount=" + loaded.amount().toPlainString(), "date=" + loaded.date()));
        if (loaded.number() != null) {
            fields.add("number=" + loaded.number());
        }
        fields.add("old=" + figure(resettled.old()));
        fields.add("new=" + figure(resettled.now()));
        audit.record(Audit.line("CLAIM_RESETTLED", loaded.sheetId(), Audit.user(connection),
                fields.toArray(String[]::new)));
    }

    private static String figure(BigDecimal due) {
        return due == null ? "n/a" : due.toPlainString();
    }
}

